void Solver::rephase() {
    // Reset the rephase counter
    rephases = 0;

    // Gradually increase the rephase limit (more aggressive on difficult problems)
    rephase_limit = rephase_limit * 1.1 + 100;

    // Adjust threshold based on recent trail performance
    threshold = (threshold * 0.8) + (trail.size() * 0.2);

    // Update saved phases based on recent local best assignments
    // Mix between current trail assignments and local best for diversification
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            // Keep current assignment if variable is assigned in trail
            saved[i] = value[i];
        } else if (rand() % 100 < 70) {
            // 70% chance to use local best, 30% to invert for exploration
            saved[i] = local_best[i];
        } else {
            saved[i] = -local_best[i];
        }
    }

    // Reset the trail threshold for tracking new local best assignments
    if (trail.size() > 0) {
        threshold = std::max((int)(trail.size() * 0.9), 100);
    }
}
